shellCommands.command:
(npx vite preview --port 4173 --strictPort > /tmp/pwcheck/preview.log 2>&1 &) ; sleep 3; cat > /tmp/pwcheck/check.mjs <<'EOF'
import { chromium } from 'playwright';
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 900, height: 700 }, colorScheme: 'light' });
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
const base = 'http://localhost:4173/';
const bodyBg = () => page.evaluate(() => ({ cls: document.body.className, bg: getComputedStyle(document.body).backgroundColor, appBg: getComputedStyle(document.querySelector('.app')).backgroundColor }));
const h1 = () => page.textContent('h1');

await page.goto(base);
console.log('home h1:', await h1(), '| initial:', JSON.stringify(await bodyBg()));
await page.screenshot({ path: '/tmp/pwcheck/home-light.png' });

// navigation
await page.click('text=Задачи');
console.log('after click Задачи: url', page.url(), 'h1:', await h1());
await page.click('text=О проекте');
console.log('after click О проекте: url', page.url(), 'h1:', await h1());
await page.goBack();
console.log('goBack -> url', page.url(), 'h1:', await h1());
await page.goto(base + '#/nonexistent');
console.log('unknown route h1:', await h1());

// tasks
await page.goto(base + '#/tasks');
await page.fill('input[placeholder="Новая задача"]', 'Тестовая задача');
await page.click('button[type=submit]');
const items = await page.$$eval('.task-list__item', els => els.map(e => e.textContent.trim()));
console.log('tasks after add:', JSON.stringify(items));
await page.click('.task-list__item:has-text("Тестовая задача") input[type=checkbox]', { force: true }).catch(e => console.log('checkbox click err', e.message));
console.log('done class count:', await page.$$eval('.task-list__title--done', e => e.length));
await page.click('.task-list__item:has-text("Тестовая задача") button');
console.log('tasks after delete:', (await page.$$('.task-list__item')).length);
await page.screenshot({ path: '/tmp/pwcheck/tasks-light.png' });

// theme toggle
await page.goto(base);
await page.click('text=Тёмная тема');
await page.waitForTimeout(300);
console.log('after toggle dark:', JSON.stringify(await bodyBg()));
await page.screenshot({ path: '/tmp/pwcheck/home-dark.png' });
await page.reload();
await page.waitForTimeout(300);
console.log('after reload (persisted):', JSON.stringify(await bodyBg()), 'stored=', await page.evaluate(() => localStorage.getItem('app-theme')));
await page.click('text=Тёмная тема');
await page.waitForTimeout(300);
console.log('toggled back light:', JSON.stringify(await bodyBg()));
await browser.close();
console.log('ERRORS:', JSON.stringify(errors));
EOF
cd /tmp/pwcheck && timeout 120 node check.mjs
